CREATE TABLE IF NOT EXISTS support_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), subject text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES support_threads(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES users(id), sender_role text NOT NULL CHECK(sender_role IN ('customer','admin')), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS store_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token text UNIQUE NOT NULL, created_by uuid NOT NULL REFERENCES users(id), email text, expires_at timestamptz, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS store_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invite_id uuid NOT NULL REFERENCES store_invites(id), applicant_name text NOT NULL, email text NOT NULL, phone text NOT NULL, store_name text NOT NULL, store_slug text NOT NULL, logo_url text, status text NOT NULL DEFAULT 'pending_admin_review', admin_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS store_change_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES stores(id), requested_by uuid NOT NULL REFERENCES users(id), changes jsonb NOT NULL, status text NOT NULL DEFAULT 'pending_admin_review', admin_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
